const superagent = require("superagent");
const snekfetch = require("snekfetch");

class Discord_Bots_GG {

    /**
   * @param {string} id ID bot.
   * @param {string} apitoken API Token.
   */

  constructor (id, apitoken) {
    if (typeof id != 'string') throw new Error('The ID must be a string.');
    if (typeof apitoken != 'string') throw new Error('The API Token must be a string.');

    this.id = id;
    this.apitoken = apitoken;
  }

  /**
   * Post Stats to Discord Bots.
   * @param {number|number[]} guildCount Server Count of your bot.
   * @returns {Promise<Object>}
   */

  postStats (guildCount) {
    if (!guildCount && !this.client) throw new Error('The postStats requires 1 argument.');
    return new Promise((resolve, reject) => {
      snekfetch.post(`https://discord.bots.gg/api/v1/bots/${this.id}/stats`)
      .set('Authorization', this.apitoken)
      .send({ server_count: guildCount })
      .then((bots) => {
				resolve(bots.body);
			}).catch((error) => {
				reject(new Error(error));
			});
    });
  }
};

module.exports = Discord_Bots_GG;